use nntune_core::pool_channel::{
    self, AuthError, Channel, CANDIDATE_PATH, MAX_CLOCK_SKEW_SECS, MAX_REQUEST_BYTES,
    REGISTRY_PATH, RESOLVE_PATH,
};

const KEY: &[u8] = b"synthetic-resolver-secret-32-bytes";
const NOW: u64 = 1_800_000_000;

#[test]
fn resolver_compatibility_vector_matches_independent_hmac_sha256() {
    let header = pool_channel::authorization_header(Some(KEY), REGISTRY_PATH, NOW, b"{}").unwrap();
    // Independent Python hmac/hashlib vector, not generated by this signer.
    assert_eq!(
        header,
        "PoolResolver 1800000000.0488cb5f243350059a3bcf12a9ba66d77cb63610f7045be7b33e4c9563f4dda1"
    );
    assert_eq!(
        pool_channel::verify(Some(KEY), REGISTRY_PATH, Some(&header), b"{}", NOW),
        Ok(())
    );
}

#[test]
fn account_vector_is_domain_separated_even_with_the_same_secret() {
    let account = Channel::Account
        .authorization_header(Some(KEY), CANDIDATE_PATH, NOW, b"{}")
        .unwrap();
    assert_eq!(
        account,
        "PoolAccount 1800000000.0161a3b7fb6de57a4da3fa12e377a18e84c637998b5191c31df673649739cbda"
    );
    let renamed = account.replacen("PoolAccount", "PoolResolver", 1);
    assert_eq!(
        pool_channel::verify(Some(KEY), REGISTRY_PATH, Some(&renamed), b"{}", NOW),
        Err(AuthError::Unauthorized)
    );
    assert!(Channel::Account
        .authorization_header(Some(KEY), REGISTRY_PATH, NOW, b"{}")
        .is_none());
    assert!(pool_channel::authorization_header(Some(KEY), CANDIDATE_PATH, NOW, b"{}").is_none());
}

#[test]
fn both_channels_bind_path_body_time_and_key() {
    for (channel, path) in [
        (Channel::Resolver, REGISTRY_PATH),
        (Channel::Resolver, RESOLVE_PATH),
        (Channel::Account, CANDIDATE_PATH),
    ] {
        let header = channel
            .authorization_header(Some(KEY), path, NOW, b"{\"id\":1}")
            .unwrap();
        assert_eq!(
            channel.verify(Some(KEY), path, Some(&header), b"{\"id\":1}", NOW),
            Ok(())
        );
        for (key, modified_path, body, time) in [
            (KEY, "/unknown", &b"{\"id\":1}"[..], NOW),
            (KEY, path, &b"{ \"id\":1}"[..], NOW),
            (KEY, path, &b"{\"id\":2}"[..], NOW),
            (KEY, path, &b"{\"id\":1}"[..], NOW + MAX_CLOCK_SKEW_SECS + 1),
            (KEY, path, &b"{\"id\":1}"[..], NOW - MAX_CLOCK_SKEW_SECS - 1),
            (
                &b"different-synthetic-key-32-bytes!"[..],
                path,
                &b"{\"id\":1}"[..],
                NOW,
            ),
        ] {
            assert_eq!(
                channel.verify(Some(key), modified_path, Some(&header), body, time),
                Err(AuthError::Unauthorized)
            );
        }
        for time in [NOW - MAX_CLOCK_SKEW_SECS, NOW + MAX_CLOCK_SKEW_SECS] {
            assert_eq!(
                channel.verify(Some(KEY), path, Some(&header), b"{\"id\":1}", time),
                Ok(())
            );
        }
    }
}

#[test]
fn malformed_headers_missing_keys_and_oversized_requests_refuse() {
    for (channel, path) in [
        (Channel::Resolver, REGISTRY_PATH),
        (Channel::Account, CANDIDATE_PATH),
    ] {
        for key in [None, Some(&b"short"[..]), Some(&b""[..])] {
            assert!(channel
                .authorization_header(key, path, NOW, b"{}")
                .is_none());
            assert_eq!(
                channel.verify(key, path, None, b"{}", NOW),
                Err(AuthError::NotConfigured)
            );
        }
        for header in [
            None,
            Some(""),
            Some("Bearer synthetic"),
            Some("PoolResolver 1800000000.bad"),
            Some("PoolAccount NaN.bad"),
            Some("PoolAccount 18446744073709551616.bad"),
            Some("PoolAccount 1800000000.bad.extra"),
        ] {
            assert_eq!(
                channel.verify(Some(KEY), path, header, b"{}", NOW),
                Err(AuthError::Unauthorized)
            );
        }
        let max = vec![b' '; MAX_REQUEST_BYTES];
        let header = channel
            .authorization_header(Some(KEY), path, NOW, &max)
            .unwrap();
        assert_eq!(
            channel.verify(Some(KEY), path, Some(&header), &max, NOW),
            Ok(())
        );
        let over = vec![b' '; MAX_REQUEST_BYTES + 1];
        assert!(channel
            .authorization_header(Some(KEY), path, NOW, &over)
            .is_none());
        assert_eq!(
            channel.verify(Some(KEY), path, Some(&header), &over, NOW),
            Err(AuthError::Unauthorized)
        );
    }
}
